```ts
import { createActionToolBridge } from "./index.js";
const bridge = createActionToolBridge(registry, { tools: [{
  kind: 'action', actionId: 'table.filter', name: 'filter_table',
  description: 'Filter the visible table',
  inputSchema: { type: 'object', properties: { query: { type: 'string' } },
    required: ['query'], additionalProperties: false },
  mapOutput: () => ({ updated: true }),
}] });
const result = await bridge.execute({ callId: 'call-1', name: 'filter_table', arguments: { query: 'Tokyo' } });
```

```ts
import { createExecutionSession } from "./index.js";
const session = createExecutionSession();
const result = await session.run('Import', async ({ signal, reportProgress }) => {
  reportProgress({ completed: 0, total: 1 });
  const response = await fetch('/import', { method: 'POST', signal });
  if (!response.ok) throw new Error('Import failed');
  reportProgress({ completed: 1, total: 1 });
});
```

